INSERT INTO answer_choices (question_id, answer_text, is_correct, position) VALUES ((SELECT id FROM questions WHERE question_text = 'Comment conserver au mieux des aliments périssables ?'), 'Les laisser sur le plan de travail toute la journée.', 0, 1);
