INSERT INTO questions (topic, question_text) VALUES ('Cuisine', 'Quel couteau convient le mieux pour émincer des légumes ?');
INSERT INTO answer_choices (question_id, answer_text, is_correct, position) VALUES ((SELECT id FROM questions WHERE question_text = 'Quel couteau convient le mieux pour émincer des légumes ?'), 'Un couteau à beurre.', 0, 1);
