INSERT INTO questions (topic, question_text) VALUES ('Cuisine', 'Que signifie “faire revenir” un aliment ?');
INSERT INTO answer_choices (question_id, answer_text, is_correct, position) VALUES ((SELECT id FROM questions WHERE question_text = 'Que signifie “faire revenir” un aliment ?'), 'Le laisser refroidir au réfrigérateur.', 0, 1);
