INSERT INTO questions (topic, question_text) VALUES ('Cuisine', 'Pourquoi faut-il séparer cru et cuit ?');
INSERT INTO answer_choices (question_id, answer_text, is_correct, position) VALUES ((SELECT id FROM questions WHERE question_text = 'Pourquoi faut-il séparer cru et cuit ?'), 'Pour obtenir davantage de vaisselle colorée.', 0, 1);
