INSERT INTO questions (topic, question_text) VALUES ('Cuisine', 'Comment vérifier la cuisson d’un gâteau ?');
INSERT INTO answer_choices (question_id, answer_text, is_correct, position) VALUES ((SELECT id FROM questions WHERE question_text = 'Comment vérifier la cuisson d’un gâteau ?'), 'En ouvrant le four toutes les trente secondes.', 0, 1);
