INSERT INTO questions (topic, question_text) VALUES ('Cuisine', 'Quelle est une bonne pratique pour doser le sel ?');
INSERT INTO answer_choices (question_id, answer_text, is_correct, position) VALUES ((SELECT id FROM questions WHERE question_text = 'Quelle est une bonne pratique pour doser le sel ?'), 'Saler abondamment avant même de goûter.', 0, 1);
